  function validate(p){if(!p||p.format!=='jago-studio-transfer'||p.version!==1||!names[p.sourceStudio]||typeof p.sourceProjectId!=='string'||p.sourceProjectId.length>100||typeof p.id!=='string'||!/^[a-f0-9-]{36}$/i.test(p.id)||typeof p.name!=='string'||p.name.length>160||!Number.isInteger(p.width)||!Number.isInteger(p.height)||p.width<1||p.height<1||p.width*p.height>2097152||!Array.isArray(p.layers)||!p.layers.length||p.layers.length>12||!Number.isFinite(p.seconds)||p.seconds<.25||p.seconds>12)throw Error('That is not a supported Jago studio transfer.');if(p.original&&(!names[p.original.studio]||p.original.extension!==({wobble:'.jago',dither:'.jagodither',repeat:'.jagorepeat',worldbuilding:'.jagoworld',material:'.jagomaterial',music:'.jagomusic',library:'.jagolibrary'})[p.original.studio]||!p.original.data||typeof p.original.data!=='object'))throw Error('The editable original has an unsupported format.');validateAudio(p.audio);validateFiles(p.files);let pixels=0,bytes=0;for(const l of p.layers){if(typeof l.id!=='string'||l.id.length>100||typeof l.name!=='string'||l.name.length>160||!Array.isArray(l.frames)||!l.frames.length||l.frames.length>288)throw Error('The transfer has an invalid layer.');let end=0;for(const f of l.frames){if(!Number.isFinite(f.time)||!Number.isFinite(f.duration)||f.duration<=0||Math.abs(f.time-end)>.002||typeof f.src!=='string'||!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(f.src))throw Error('The transfer has invalid images or timing.');end=f.time+f.duration;bytes+=f.src.length;pixels+=p.width*p.height;}if(Math.abs(end-p.seconds)>.002)throw Error('The layer timing does not match the loop.');}bytes+=(p.audio||[]).reduce((n,a)=>n+a.src.length,0)+(p.files||[]).reduce((n,a)=>n+a.src.length,0);if(bytes>100e6||pixels>96000000)throw Error('That transfer is too large. Use fewer frames, layers or smaller artwork.');return p}
